using FinancePro.Core.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace FinancePro.Data.Configurations;
public sealed class VendaItemConfiguration : IEntityTypeConfiguration<VendaItem> { public void Configure(EntityTypeBuilder<VendaItem> b){ b.ToTable("VendaItens"); b.Property(x=>x.Quantidade).HasColumnType("decimal(18,4)"); b.Property(x=>x.PrecoUnitario).HasColumnType("decimal(18,2)"); b.Property(x=>x.DescontoPercentual).HasColumnType("decimal(5,2)"); b.Property(x=>x.IvaPercentual).HasColumnType("decimal(5,2)"); b.HasOne(x=>x.ContaReceber).WithMany(x=>x.Itens).HasForeignKey(x=>x.ContaReceberId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x=>x.Produto).WithMany().HasForeignKey(x=>x.ProdutoId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.ContaReceberId,x.ProdutoId}); } }
